INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 3, 'theory', 'Quiz: linked lists');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 3, 0, 'You need to insert a node X after a known node B in a singly linked list. Which order of assignments is correct?', '["First B.next = X, then X.next = B.next", "First X.next = B.next, then B.next = X", "The order doesn''t matter: the operations are independent", "First delete B, then insert X"]', 1, 'If you assign B.next = X first, the old tail of the list is lost: nothing points to it anymore. First we remember the tail in X, then redirect B.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 3, 1, 'The fast pointer, stepping by two, has reached the end of a list of seven nodes. Where is the slow pointer (stepping by one) at that moment?', '["At the first node", "At the third node", "At the fourth node, the middle of the list", "At the sixth node"]', 2, 'The slow pointer has covered exactly half: with seven nodes the fast one makes three jumps and the slow one three steps, so it stands at the fourth node, the middle.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 3, 2, 'Why does a linked list beat an array in merge sort?', '["A list can''t be split in half, but an array can", "Merging lists rearranges references and needs no auxiliary buffer", "Merge sort on a list runs in linear time", "Lists don''t need recursion"]', 1, 'Merging two sorted lists moves nodes into the result without copying; an array needs a buffer of length n for merging. The time stays n log n.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 3, 3, 'In a ring buffer the head equals the tail. What does that mean?', '["The queue is empty", "The queue is full", "You can''t tell from the indexes alone: you need a counter of occupied slots or a spare cell", "An error occurred: this can''t happen"]', 2, 'Both states, an empty and a full queue, give equal indexes. That is why we store the number of occupied slots (or always leave one cell free).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 3, 4, 'Why does a queue from two stacks give amortized constant time for removal, even though pouring costs linear time?', '["Pouring happens on every removal, but very fast", "Each element is poured at most once in its whole lifetime", "The second stack is always empty", "Pouring runs in parallel with insertion"]', 1, 'An element goes into the input stack, is poured once into the output stack, and is removed. The expensive operation is paid for by many cheap ones, the amortized analysis from the chapter on complexity.');
